package com.zhuqiyun;
import com.zhuqiyun.platform.*;import com.zhuqiyun.inventory.StocktakeService;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static com.zhuqiyun.domain.Rules.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:adjustments;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;NON_KEYWORDS=VALUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.flyway.enabled=false","spring.sql.init.mode=always","spring.sql.init.schema-locations=classpath:db/migration/V1__schema.sql,classpath:db/migration/V4__payment_application_approval.sql,classpath:db/migration/V5__procurement_adjustments.sql,classpath:db/migration/V6__scoped_read_permissions.sql,classpath:db/migration/V7__contract_payment_stages.sql,classpath:db/migration/V8__inventory_stocktakes.sql,classpath:db/migration/V9__explicit_issue_sources.sql,classpath:db/migration/V10__payment_plan_authority.sql,classpath:db/migration/V11__company_inventory_authority.sql,classpath:db/migration/V12__stocktake_versions.sql,classpath:db/migration/V13__import_batches.sql","app.seed=true"})
class StocktakeTest {
 @Autowired Db db;@Autowired StocktakeService service;long warehouse,material;
 void as(String role){long id=((Number)db.one("SELECT id FROM users WHERE username=?",role).get("id")).longValue();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,List.of()));}
 @BeforeEach void setup(){as("warehouse");warehouse=db.insert("warehouses",row("code",code("COUNT"),"name","盘点隔离仓"));material=((Number)db.one("SELECT id FROM materials ORDER BY id LIMIT 1").get("id")).longValue();}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 long id(Map<String,Object> r){return ((Number)r.get("id")).longValue();}
 Map<String,Object> line(long m,String qty,String price){return row("material_id",m,"counted_quantity",qty,"snapshot_revision",service.snapshot(warehouse,m).get("revision"),"gain_unit_price",price,"reason","实地核对差异");}
 Map<String,Object> create(String qty,String price){return service.save(null,row("warehouse_id",warehouse,"items",List.of(line(material,qty,price))));}
 Map<String,Object> submit(Map<String,Object> h){return service.submit(id(h),row("expected_version",h.get("version")));}
 Map<String,Object> approve(Map<String,Object> h){as("boss");return service.review(id(h),row("expected_version",h.get("version"),"decision","APPROVED"));}
 void status(int code,org.junit.jupiter.api.function.Executable work){assertEquals(code,assertThrows(ResponseStatusException.class,work).getStatusCode().value());}
 void amount(String expected,Object value){assertEquals(0,new BigDecimal(expected).compareTo(dec(value)));}
 Map<String,Object> stock(){return db.one("SELECT * FROM inventory WHERE warehouse_id=? AND material_id=?",warehouse,material);}
 @Test void onlyIndependentApprovalPostsOnceAndNeverPostsProjectCost(){long costs=((Number)db.one("SELECT COUNT(*) n FROM costs").get("n")).longValue();var h=create("3","12.3456");assertTrue(db.list("SELECT id FROM inventory WHERE warehouse_id=?",warehouse).isEmpty());var pending=submit(h);assertTrue(db.list("SELECT id FROM stock_movements WHERE stocktake_id=?",id(h)).isEmpty());as("admin");db.jdbc().update("UPDATE stocktakes SET applicant_id=? WHERE id=?",db.one("SELECT id FROM users WHERE username='admin'").get("id"),id(h));status(409,()->service.review(id(h),row("expected_version",pending.get("version"),"decision","APPROVED")));db.jdbc().update("UPDATE stocktakes SET applicant_id=? WHERE id=?",db.one("SELECT id FROM users WHERE username='warehouse'").get("id"),id(h));var approved=approve(pending);amount("3",stock().get("quantity"));amount("37.04",stock().get("stock_value"));status(409,()->approve(pending));as("warehouse");status(409,()->service.save(id(h),row("warehouse_id",warehouse,"expected_version",approved.get("version"),"items",List.of(line(material,"0",null)))));var flow=db.one("SELECT * FROM stock_movements WHERE stocktake_id=?",id(h));assertNull(flow.get("project_id"));assertEquals("STOCKTAKE_GAIN",flow.get("kind"));assertEquals(costs,((Number)db.one("SELECT COUNT(*) n FROM costs").get("n")).longValue());}
 @Test void noPriceNoImplicitZeroAndNoSelfApproval(){status(409,()->create("1",null));status(409,()->create(null,"10"));as("warehouse");var h=submit(create("1","10"));status(403,()->service.review(id(h),row("expected_version",h.get("version"),"decision","APPROVED")));as("manager");status(403,()->service.detail(id(h)));}
 @Test void changedSnapshotAndAbaRevisionCannotOverwriteStock(){approve(submit(create("3","10")));as("warehouse");var pending=submit(create("2",null));long inventory=id(stock());db.update("inventory",inventory,row("quantity",new BigDecimal("3")));status(409,()->approve(pending));amount("3",stock().get("quantity"));assertTrue(db.list("SELECT id FROM stock_movements WHERE stocktake_id=?",id(pending)).isEmpty());as("warehouse");var draft=service.withdraw(id(pending),row("expected_version",pending.get("version"),"reason","账面变更"));status(409,()->service.refresh(id(draft),row("expected_version",draft.get("version"))));var refreshed=service.refresh(id(draft),row("expected_version",draft.get("version"),"confirm_snapshot",true));approve(submit(refreshed));amount("2",stock().get("quantity"));amount("20",stock().get("stock_value"));}
 @Test void multilineApprovalRollsBackEarlierAdjustmentWhenLaterSnapshotChanged(){long other=((Number)db.one("SELECT id FROM materials WHERE id<>? ORDER BY id LIMIT 1",material).get("id")).longValue();var h=service.save(null,row("warehouse_id",warehouse,"items",List.of(line(material,"2","10"),line(other,"2","20"))));var pending=submit(h);db.insert("inventory",row("warehouse_id",warehouse,"material_id",other,"quantity",new BigDecimal("1"),"stock_value",new BigDecimal("20"),"average_price",new BigDecimal("20")));status(409,()->approve(pending));assertTrue(db.list("SELECT id FROM inventory WHERE warehouse_id=? AND material_id=?",warehouse,material).isEmpty());assertTrue(db.list("SELECT id FROM stock_movements WHERE stocktake_id=?",id(h)).isEmpty());assertEquals("PENDING",db.one("SELECT status FROM stocktakes WHERE id=?",id(h)).get("status"));}
 @Test void positiveBookValueRemainsUsableEvenWhenRoundedAverageIsZero(){
  db.insert("inventory",row("warehouse_id",warehouse,"material_id",material,"quantity",new BigDecimal("1000000"),"stock_value",new BigDecimal("0.01"),"average_price",BigDecimal.ZERO));
  assertEquals(true,service.snapshot(warehouse,material).get("has_positive_price"));approve(submit(create("1000001",null)));amount("0.01",stock().get("stock_value"));amount("1000001",stock().get("quantity"));
 }
 @Test void staleEditsRejectedAndCorrectionIsExplicitNewDocument(){var old=create("2","10");var saved=service.save(id(old),row("warehouse_id",warehouse,"expected_version",old.get("version"),"items",List.of(line(material,"3","10"))));status(409,()->service.submit(id(old),row("expected_version",old.get("version"))));var approved=approve(submit(saved));as("warehouse");var correction=service.save(null,row("warehouse_id",warehouse,"correction_of",id(approved),"items",List.of(line(material,"2",null))));assertEquals(id(approved),((Number)correction.get("correction_of")).longValue());approve(submit(correction));amount("2",stock().get("quantity"));amount("20",stock().get("stock_value"));}
}
